// The progress ring's band as a table (#558): every pixel the band covers or dfw_draw_band gives a value, in scan
// order (y, then x), with the parts of its color that never change. Generated by gen/band_table_gen.c into
// src/band_table.c: don't edit that file; regenerate it with `make tables` (the tests check it is current).
#ifndef DFW_BAND_TABLE_H
#define DFW_BAND_TABLE_H
#include "dfw.h"

typedef struct {
    /// The pixel in the frame's coordinates (below 0 or past 197 outside the square).
    int16_t x, y;
    /// Whether the band covers any of it (else it is only the layer's black), and whether it is in the band's clear
    /// annulus outside the square: one dfw_draw_band writes.
    uint8_t ring, layer;
    /// The band's cover of the pixel, and the part clockwise of the 12 o'clock ray (the fill's start edge).
    float band, start;
    /// The track blended over what lies under the pixel.
    dfw_pixel track;
} dfw_band_entry;

extern const dfw_band_entry dfw_band_table[];
extern const int dfw_band_entries;

#endif
